import{_ as o,o as c,c as d,a3 as a}from"./chunks/framework.qCVWde4n.js";const h=JSON.parse('{"title":"hub：每台设备都是一个 Muse","description":"","frontmatter":{},"headers":[],"relativePath":"zh/hub.md","filePath":"zh/hub.md"}'),n={name:"zh/hub.md"};function s(t,e,r,i,l,p){return c(),d("div",null,[...e[0]||(e[0]=[a(`<h1 id="hub-每台设备都是一个-muse" tabindex="-1">hub：每台设备都是一个 Muse <a class="header-anchor" href="#hub-每台设备都是一个-muse" aria-label="Permalink to &quot;hub：每台设备都是一个 Muse&quot;">​</a></h1><p>在手机、电脑和浏览器上登录同一个 nanoMuse Cloud 账号，它们就能看见彼此。每台设备跑着自己的 Muse，带着自己的手（手机上的 App 和沙箱，电脑上的 shell 和屏幕），其中任何一台都可以从任何网络拜托任何另一台做点什么。网页控制台自己没有手；它是通往其余设备的前门。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>phone ──┐                         ┌── computer (nanoMuse Desktop)</span></span>
<span class="line"><span>        ├──▶  nanoMuse Cloud  ◀───┤</span></span>
<span class="line"><span>web  ───┘        /v1/hub          └── another phone / computer</span></span></code></pre></div><p>每台设备向中继开一条出站的 WebSocket 并一直保持。设备上不监听任何东西，不需要端口转发，也不需要同一个 Wi-Fi；中继只在一个账号的设备之间转发帧，从不看任务里面是什么。添加一台电脑就是这么做的：在上面装 nanoMuse Desktop，用同一个账号登录，不用手动下载什么，也不用输什么码。这也是唯一的入口：那个通过局域网配对的独立主机脚本（0.1.13–0.1.23）已经去掉了，所以手机列表里缺了一台电脑，几乎总是因为它登录的是另一个账号；手机上的 <em>设置 → 电脑</em> 显示手机用的是哪个账号。</p><h2 id="what-you-can-say" tabindex="-1">你可以说什么 <a class="header-anchor" href="#what-you-can-say" aria-label="Permalink to &quot;你可以说什么 {#what-you-can-say}&quot;">​</a></h2><p>在手机上，任何聊天里：</p><ul><li>「在我 Mac 上列一下下载文件夹」：<code>nanomuse-pc ls ~/Downloads --on mac</code></li><li>「让电脑把项目编译一遍，把日志发给我」：<code>nanomuse-pc task &quot;…&quot; --on desk</code></li><li>「电脑截个图给我看」：<code>nanomuse-pc screen --on desk</code></li></ul><p>在电脑上，nanoMuse 桌面版里（或终端里的 <code>nanomuse chat</code>）：</p><ul><li>「在我手机上截个图」：<code>device_screen</code></li><li>「让手机的 Muse 把最后一条通知读给我」：<code>delegate</code></li><li>「给手机发个通知：晚饭好了」：<code>device_notify</code></li></ul><p>在网页控制台（<code>/app</code>）里：选一台设备，打字。任务在那台设备的 Muse 上跑；审批以卡片的形式显示在页面里。</p><p>hub 上传递两类请求：</p><ul><li><p><strong>动作。</strong> <code>info</code>、<code>shell</code>、<code>files</code>、<code>file.get</code>、<code>file.put</code>、<code>open</code>、<code>screen</code>、<code>notify</code>。原始、即时。一条 <code>shell</code> 命令在发出之前先在<em>发起方</em>判定，用的和本地命令同一套阶梯（手机的 ShellGuard、桌面的 <code>guard.py</code>）：读取和构建静默放行，删除 / 发送 / 付款 / 系统命令则等发起设备上的审批卡片。</p></li><li><p><strong>任务。</strong> <code>task {text, conversation?, language?, stream?}</code>：用自然语言描述的一整件事，交给目标设备自己的 Muse，在它自己的一个对话里完成（<code>conversation</code> 指定是哪个对话，缺省时用发起方的 id）。<code>language</code>（运行时 1.0.0 起，可选）是发起设备界面语言的 BCP-47 标签；目标设备用这个语言作答，而不是从文字里猜。可能要几分钟。那个 Muse 碰到需要审批的事时不会自己拿主意：问题以 <code>event {stage:&quot;approval&quot;}</code> 传回来，发起设备显示它惯常的卡片（手机上是 RiskGate，桌面上是终端提示，网页控制台里是一张卡片）。回答以 <code>approve {approval_id, allow}</code> 传回去。发起设备可以用 <code>stop {call}</code>（它那条 <code>task</code> 帧的 id）或 <code>stop {conversation}</code>（它指定的对话，没指定时就是它自己的那个按设备分的对话）结束自己发起的任务：目标设备在进行中的一步之后取消运行，回答 <code>{stopped: true}</code>，随后那条 <code>task</code> 调用本身以 <code>cancelled</code> 失败。<code>{stopped: false}</code> 表示没有属于发起方的可停之事；一台设备绝不会停掉别的设备发起的任务。运行时、桌面版和手机都这样做。对一个已经在跑任务的对话再发 <code>task</code>，会立刻以 <code>busy</code> 失败（运行时）：发起方等前一个答完，或者先停掉它，再问一次。超过 hub 时限还没答的任务以 <code>timeout</code> 失败，目标那边的 Muse 跑不起来的以 <code>failed</code> 失败。<code>stream: true</code> 表示发起方把每条 <code>text</code> 画在上一个 <code>tool</code> 之后那段文字的位置上；nanoMuse 桌面版这时还会发 <code>text {text, interim, partial: true}</code>，带着模型正在写的那条消息的文字，最多每 250 毫秒一次，写完的消息照旧发。没有要求的发起方每条消息只收到一次（Android 的 <code>nanomuse-pc task</code> 把每条 <code>text</code> 列成一步）；运行时暂时忽略 <code>stream</code>。</p><p>任务运行期间，目标设备发送 <code>event</code> 帧，<code>body.stage</code> 告诉发起方该画什么，于是这次运行在发起方的聊天里读起来和在目标设备自己那里一样：工具开始时是 <code>tool {id, name, summary}</code>，结束时是 <code>tool_result {id, name, ok, summary}</code>（同一个 <code>id</code>）；<code>approval {approval_id, preview, risk, reason, device, timeout, grant_key}</code>，以及任一方作出决定后的 <code>approval_result {approval_id, status}</code>；<code>text {text, interim}</code> 是 Muse 一路上说的话；<code>image</code> 和 <code>file</code> 是它做出来的东西；<code>error</code>。<code>result</code> 帧带着最终答案。发起方把一条 <code>text</code> 画在上一个 <code>tool</code> 之后那段文字的位置上，所以目标设备可以把同一条消息越写越长地发好几次，发起方随之显示；每条消息只发一次的目标设备显示效果不变。<code>grant_key</code>（1.0.6 起）是发起方记住的回答所覆盖的范围：运行时发的是它自己的授权所用的键（工具和目标，如 <code>shell:git</code>），桌面版发的是工具加完整的主参数；没有这个字段的发送方，照旧按 <code>preview</code> 的前 60 个字符记，而两个不同的步骤可能开头相同。</p></li><li><p><strong>编程助手。</strong> <code>coding.agents</code>、<code>coding.sessions</code>、<code>coding.session</code>、<code>coding.send</code>、<code>coding.stop</code>、<code>coding.runs</code>：电脑上的 Cursor / Codex / Claude Code 会话，由那里的运行时或桌面版从磁盘读取，并通过这些助手自己的 CLI 来驱动。<code>coding.send {agent, text, session_id?, workspace?, wait}</code> 以 <code>event</code> 帧把运行过程流式传回（<code>started</code>、<code>text</code>、<code>tool</code>、<code>done</code>、<code>error</code>，每个都带运行 id，发起方据此可以 <code>coding.stop</code>），最后以完成的运行作答。只有电脑会宣告这些动作：装了这个模块的运行时，或者桌面版。<a href="./coding-agents">coding-agents.md</a>。</p></li></ul><p>每台设备自己决定允许别人做什么。手机上，「允许其他设备操作这台手机」（<em>设置 → nanoMuse Cloud → 设备</em>）关着时，这台手机只回答 <code>info</code>，别的一概不答；它仍然能看见并操纵其他设备。运行时这时的 <code>info</code> 只报电脑的名字和系统（没有账号名、主目录、工作目录和 shell），动作列表里只有 <code>info</code>。开着时，任何<em>对</em>这台设备做事的原始动作（<code>shell</code>、<code>files</code>、<code>file.get</code>、<code>file.put</code>、<code>open</code>、<code>screen</code>、<code>coding.send</code>、<code>coding.stop</code>）都要先经这台设备旁的人同意：惯常的审批卡片，「允许一次」或「对这台设备总是允许」；后一种长期有效的回答是「权限」下的一条授权（<code>remote_control:&lt;device id&gt;</code>）。nanoMuse 桌面版默认用同一张卡片询问；它的「免询问远程控制」（设置 → 设备）让账号下的每台设备都能不经卡片在那里做事。旁边没人，卡片过期后发起方听到的是 <code>not_allowed</code>。<code>info</code> 和 <code>notify</code> 从不询问；<code>task</code> 在设备自己的哨兵（Sentinel）之下运行，它的卡片照旧传回发起方。一台设备只能 <code>approve</code> 发给它的、属于它自己发起的运行的卡片，绝不能回答「是否允许它运行某事」的那张卡片；唯一的例外是电脑自己发出、标了 <code>any_device</code> 的卡片（<a href="#a-computer-s-own-cards-on-the-phone">见下</a>），账号下任何一台设备都能回答。</p><h3 id="a-computer-s-own-cards-on-the-phone" tabindex="-1">电脑自己的卡片送到手机上 <a class="header-anchor" href="#a-computer-s-own-cards-on-the-phone" aria-label="Permalink to &quot;电脑自己的卡片送到手机上 {#a-computer-s-own-cards-on-the-phone}&quot;">​</a></h3><p>nanoMuse 桌面版上的定时任务运行时，电脑旁边可能没人，所以这次运行的审批卡片也会送到账号下的手机上。这种卡片背后没有调用，所以作为推送发出（中继 0.31，见<a href="#frames">帧</a>）：电脑只在 <code>welcome.server.features</code> 列出 <code>event_push</code> 时才发，中继只转给在 <code>hello</code> 里声明了 <code>approve.any</code> 的设备（Android 和 iPhone 的 App）：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>→ event {to:&quot;*&quot;, body:{stage:&quot;approval&quot;, approval_id, preview, preview_zh, reason, app,</span></span>
<span class="line"><span>                      task:{id, title}, chat, scopes:[&quot;once&quot;, &quot;schedule&quot;?], timeout, device,</span></span>
<span class="line"><span>                      any_device:true}}</span></span>
<span class="line"><span>← call  {action:&quot;approve&quot;, args:{approval_id, allow, scope?:&quot;once&quot; | &quot;schedule&quot;}}   （发给电脑）</span></span>
<span class="line"><span>→ event {to:&quot;*&quot;, body:{stage:&quot;approval_result&quot;, approval_id, status, by?:{id, name}}}</span></span></code></pre></div><p><code>preview</code> 和 <code>preview_zh</code> 分别用英文和中文说明这一步要做什么（手机按自己的语言挑一个），<code>app</code> 是手要操作的应用，<code>task</code> 和 <code>chat</code> 是任务和它所在的对话，<code>device</code> 是那台电脑，<code>timeout</code> 是手机上卡片显示的秒数（600）。<code>scopes</code> 列出卡片除了「拒绝」之外还能给的回答：<code>schedule</code>（「此定时任务中始终允许」）只出现在只有一个任务的运行里、手的一步上；这条授权记在电脑上，从不记在手机上。<code>any_device</code> 表示账号下任何一台设备都能回答：这张卡片的 <code>approve</code> 电脑收哪台设备先发来的都算，而别的卡片只有发起那次运行的设备能答。电脑上或任何一部手机上先给出的回答算数；随后电脑推送 <code>approval_result</code>，带上 <code>status</code>（<code>approved</code>、<code>denied</code>，运行放弃了这张卡片时是 <code>cancelled</code>）和 <code>by</code>（是哪台设备答的），手机收起卡片。手机上没人及时回答时，只收起自己的卡片，什么也不发，电脑上的卡片继续等。命中支付类敏感词的卡片也会送过去：声明 <code>approve.any</code> 的只有手机，手机在锁屏之后才能回答。这件事不会在手机上运行任何东西，所以「允许其他设备操作这台手机」关着时卡片也照样显示。在后台时，Android 把卡片显示成一条通知；iOS 在 hub 连接还开着时发一条通知。</p><h3 id="proposed-proxy-fetch-the-phone-uses-the-computer-s-connection" tabindex="-1">提案 <code>proxy_fetch</code>：手机借用电脑的网络 <a class="header-anchor" href="#proposed-proxy-fetch-the-phone-uses-the-computer-s-connection" aria-label="Permalink to &quot;提案 \`proxy_fetch\`：手机借用电脑的网络 {#proposed-proxy-fetch-the-phone-uses-the-computer-s-connection}&quot;">​</a></h3><p>还没做；先写在这里，让三个实现在有人动手之前先取得一致。场景：手机的网络连不上 <code>chatgpt.com</code> 或某个服务商的主机（<a href="./own-key#when-the-provider-cannot-be-reached">own-key.md</a> 里的那张卡片），而这个人的电脑连得上。电脑的运行时通过 hub 转发那次服务商调用（只转发那个），像代理一样。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>→ call   {id, to, action:&quot;proxy_fetch&quot;,</span></span>
<span class="line"><span>          args:{method, url, headers:{…}, body?, stream?}}     body base64; stream: want SSE chunks as events</span></span>
<span class="line"><span>← event  {id, from, body:{stage:&quot;headers&quot;, status, headers:{…}}}</span></span>
<span class="line"><span>← event  {id, from, body:{stage:&quot;chunk&quot;, data}}                data base64; one per SSE chunk when stream is true</span></span>
<span class="line"><span>← result {id, ok:true, body:{status, headers:{…}, data?}}      data base64 when stream was false</span></span>
<span class="line"><span>← result {id, ok:false, error:&quot;not_allowed&quot; | &quot;host_refused&quot; | &quot;too_large&quot; | &quot;upstream&quot;, message}</span></span></code></pre></div><p>让它可以接受的几条规则，每条在提供服务的一方都是一行代码：</p><ul><li><strong>电脑上主动开启。</strong> 桌面插件只在「让我的手机借用这台电脑的网络访问服务商」打开时（<em>设置 → 设备</em>）才在 <code>hello</code> 里宣告 <code>proxy_fetch</code>；关着时，这个动作是 <code>unknown_call</code>。信任级别和 <code>device_shell</code> 相同：这台设备的「远程控制」必须开着，某台设备的第一次调用会弹出惯常的卡片，「允许一次」或「对这台设备总是允许」（一条 <code>remote_control:&lt;device id&gt;</code> 授权）。</li><li><strong>只到指定主机，不是整个互联网。</strong> 电脑只向服务商目录（<code>providers.json</code>）里的主机、<code>chatgpt.com</code> 和 <code>auth.openai.com</code>，以及它自己配置的服务商的自定义 base URL 转发；其余一律 <code>host_refused</code>。绝不转发到中继、局域网地址或 <code>file:</code>。</li><li><strong>请求头照传，秘密不留。</strong> 手机发送自己的 <code>Authorization</code>（套餐的 token、它自己的 key）；电脑原样转发，只记录主机、状态码和大小，从不记录请求头或正文。</li><li><strong>有上限。</strong> 请求正文超过 8 MB、响应单帧超过 <code>HUB_FRAME_LIMIT</code> 都是 <code>too_large</code>；流在十分钟处切断；每台发起设备同一时间只有一个调用。</li><li><strong>手机来选。</strong> 「连不上」的那张卡片只在有一台宣告了 <code>proxy_fetch</code> 的电脑在线时才提供「用我电脑的网络」这个选项；这个选择按服务商实例保存，并在实例上显示为一行，免得有人忘了自己的 key 要经过电脑。</li></ul><p>为什么这次只是设计而不是代码：hub 帧本身很小，但提供服务的一方是电脑上一个新的信任面（一个携带这个人服务商 token 的转发器），而手机的两套 HTTP 栈各自都需要一个传输层，把请求变成帧、再把帧还原成响应：三个实现，加上第四处必须对主机列表取得一致的地方，这一轮的预算老实说盖不住。在此期间，代理设置（<a href="./own-key#when-the-provider-cannot-be-reached">own-key.md</a>）覆盖了常见情形：电脑上开一个代理（Clash、一条 <code>ssh -D</code>），手机指向它。</p><h2 id="frames" tabindex="-1">帧 <a class="header-anchor" href="#frames" aria-label="Permalink to &quot;帧 {#frames}&quot;">​</a></h2><p><code>WS /v1/hub</code> 上的 JSON 文本帧，<code>Authorization: Bearer nm_…</code>（浏览器则把 key 放在 <code>hello</code> 里）。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>→ hello    {device:{id,name,kind,os,version,actions[],llm?}}   kind: phone | computer | web</span></span>
<span class="line"><span>           llm（中继 0.28，可选）：{provider, model}，这台设备跑模型所用的标识（&quot;cloud&quot;、&quot;openrouter&quot;、某个模型 id）；</span></span>
<span class="line"><span>           只收纯标识，key 和 URL 一律丢弃；记在设备行上，供运营者查看</span></span>
<span class="line"><span>← welcome  {device_id, devices:[…], server:{version,frame_limit,time,features?}}   features (relay 0.31): [&quot;event_push&quot;]</span></span>
<span class="line"><span>← devices  {devices:[{id,name,kind,os,version,actions[],online,last_seen,controllable,ip}]}</span></span>
<span class="line"><span></span></span>
<span class="line"><span>→ call     {id, to, action, args}</span></span>
<span class="line"><span>← call     {id, from:{id,name,kind}, action, args}          (delivered to the target)</span></span>
<span class="line"><span>→ event    {id, body}          ← event  {id, from, body}    progress, approvals, images</span></span>
<span class="line"><span>→ event    {to, body}          ← event  {from, body}        no id: a push to a device or &quot;*&quot; (relay 0.31, below)</span></span>
<span class="line"><span>→ result   {id, ok, body | error, message}                  ← result (to the caller)</span></span>
<span class="line"><span>← error    {code, message, id?}   device_offline · not_controllable · self_call · duplicate_call · unknown_call · timeout</span></span>
<span class="line"><span>                                  too_large · rate_limited · bad_frame · device_online · bad_key · bad_device</span></span>
<span class="line"><span></span></span>
<span class="line"><span>→ devices  {}        → rename {name}        → forget {device_id}        → ping  ← pong</span></span>
<span class="line"><span>← profile  {rev, device}       the account&#39;s name, look or connectors changed (PUT /v1/me/profile); fetch it</span></span>
<span class="line"><span>← sync     {what:&quot;conversations&quot;, cursor, from}   another device pushed or deleted synced conversations; pull /v1/sync/changes</span></span>
<span class="line"><span>← working  {cid, from, device_name, working, at, state?, detail?}  another device started (true) or finished (false) a turn in that synced conversation; on a true, since relay 0.31, what it is doing (\`state\`: working | waiting; \`detail\`: the step, up to 160 characters)</span></span></code></pre></div><p>关闭码：<code>4000</code> 期待 hello（15 秒内没有 hello，或第一帧不是 hello，二进制帧也算）、<code>4001</code> key 无效（原因 <code>bad_key</code> 或 <code>account_deleted</code>；账号在连接期间被删除或停用时为 <code>account_gone</code>；从中继 0.25.0 起，连接期间 key 刚被吊销时也会收到 <code>bad_key</code>：另一台设备点了「在所有设备上退出」、在账号页退出了这个登录，或这台设备自己退出登录，这样丢失的手机会立刻断线，其他设备看到它离线）、<code>4002</code> 设备无效、<code>4003</code> 被同一设备 id 的更新连接顶替，或者，带原因 <code>hub_paused</code>（中继 0.22）时，是运营者关掉了 hub 或整个服务：客户端应等一会儿再重连，而不是立刻重试（<a href="./cloud#controls">cloud.md › 控制</a>）；<code>4008</code> 帧太多（无视了下面的限速），或者带原因 <code>too_many_connections</code>（中继 0.30）时是连接太多：同一个地址一分钟内开了 60 条以上，或者这个账号已经有 32 台设备在线（同一台设备重新顶替自己的位置不算），以及 <code>4009</code> 读得太慢（这条连接上已经积压了 512 帧或 32 MB 而对方一直不读；客户端像遇到任何网络断开一样退避重连）。发往某台设备的帧从不等那台设备：每条连接各有一个队列，按顺序随 socket 排空写出；一部卡住的手机不会拖住正在呼叫它的电脑。</p><p><code>Authorization</code> 头里的 key 被拒时，处理方式与 <code>hello</code> 里的 key 被拒一致：握手完成，先发一个带 code 的 <code>error</code> 帧，再以 <code>4001</code> 关闭。客户端看到 <code>4001</code> 或 <code>4002</code> 就离开退避重连，把 hub 显示为「被拒绝」并请人重新登录（运行时仍每分钟试一次，这样在中继上恢复的 key 不用重启也能接回来）；其他关闭都视为网络问题，按退避重试。网络已经断了而 socket 还开着（笔记本睡过一觉、换了 Wi-Fi）时收不到 <code>pong</code>：运行时的客户端用协议自带的 ping，超时 20 秒；桌面版的客户端在两个 <code>ping</code> 帧之间什么都没收到（约 50 秒）就丢掉这条 socket，照样退避重连。</p><p>中继 0.31 起，<code>event</code> 也可以不带 <code>id</code> 发出：这是一次推送，不是某个调用的进度。电脑用它发自己的审批卡片（这种卡片背后没有调用），以及「这张卡片已经有人答了」。<code>to</code> 是一台设备的 id，或 <code>&quot;*&quot;</code> 表示账号下所有设备；两种情况下中继都只转给在 <code>hello</code> 里声明了 <code>approve.any</code> 的设备，不回发给发送方，所以发送方不用自己维护名单，旧版 App 也收不到。只放行 <code>approval</code> 和 <code>approval_result</code> 两种 stage，其他的丢掉并记日志。一台设备每分钟最多推 30 条（超过回 <code>rate_limited</code>），每条 <code>body</code> 最多 16 KB（超过回 <code>too_large</code>）。支持这件事的中继在 <code>welcome.server.features</code> 里列出 <code>event_push</code>；客户端看到它才推送，所以旧中继收不到推送。</p><p>中继不认识的帧（没有处理器的 <code>type</code>、不是 JSON 对象的文本帧、二进制帧）都回 <code>error bad_frame</code>，连接保持打开，所以新客户端对着旧中继只会丢一帧，不会掉线。超过 <code>frame_limit</code> 的帧回 <code>too_large</code>；每秒超过 60 帧或 8 MB 回 <code>rate_limited</code>（每秒最多提醒一次，多出的帧被丢弃），持续下去则以 <code>4008</code> 关闭。15 分钟内没人应答的 <code>call</code> 向发起方回 <code>timeout</code>（中继在有 call 或 <code>ping</code> 到达时检查，所以一个会 ping 的发起方在期限过后一分钟内就能听到）；对当前在线的设备发 <code>forget</code> 会被拒绝，回 <code>device_online</code>。</p><p>设备 id 按安装生成（<code>phone-…</code>、<code>pc-…</code>）；名字是给人看的，可以在设备上改。<code>web</code> 设备从不作为目标，也不会被记住。<code>file.get</code>、<code>file.put</code> 和 <code>screen</code> 的正文以 base64 携带字节（<code>data</code>）并附 <code>mime</code>；桌面拒绝超过 8 MB 的文件，中继拒绝超过 <code>HUB_FRAME_LIMIT</code> 的帧。</p><p>从中继 0.27 起，一份凭据只属于一个 Hub 身份。凭据签发时可以用 <code>device_id</code> 和 <code>device_kind</code> 固定 <code>device.id</code> 与 <code>device.kind</code>（<code>POST /v1/auth/verify</code> 和 <code>/login</code>）； 签发时没带的凭据，则在第一次通过的 <code>hello</code> 时登记。同一份凭据重连仍会顶替自己的旧 套接字，改报其他 id 或类型会得到 <code>bad_device</code>。一个仍有效的 key 持有的 id，只有更晚 一次验证码或密码登录签发的 key 才能接手（手机没退出就又登录了一次、运行时的保险库 重置了、退出登录没传到中继）：旧 key 仍能打开账号，但不再代表这台设备。吊销或过期 的 key 会释放它的 id。session key（<code>/v1/auth/session-key</code>，nanoMuse Web 的容器）只能 登记没人持有的 id，从不接手别人的。现有客户端保留原 key，下次连接时登记；登录时 带上身份的客户端在登录时就绑定。</p><p>智能体的名字和形象属于账号，不属于某台设备：中继上的 <code>GET</code> / <code>PUT /v1/me/profile</code> 保存它们（小龙、某个颜色底上的 emoji，或者形象工作室里画的一张形象及其五张小图），后写的胜出，一个 <code>profile</code> 帧通知其他设备去取新的 <code>rev</code>。运行时在 <code>nanomuse/hub/profile.py</code> 里做这件事，手机在 <code>io.github.nanomuse.cloud.ProfileSync</code> 里做；写入的那台设备会跳过自己的回声。</p><p>同一份 profile 还带着<strong>哪台设备连接了什么</strong>（0.1.34）：一个 <code>connectors</code> 列表，每一项有连接器的 id 和标签、有地址的话还有地址、登录方式（<code>oauth</code>、<code>key</code> 或 <code>open</code>）、设备的名字和 id、是否启用，以及时间。一台设备只写自己持有的那些项；中继保留其他设备的项，列表上限 64 项，并拒绝任何带有 token、secret、key、authorization 或 password 字段的项；凭据绝不离开登录它的那台设备。其他设备在连接器目录下把这些项列为「已在 &lt;device&gt; 上连接，在这里登录即可在这台设备上使用」，照常的本地登录就是对应的操作。</p><p>中继 0.29 起，profile 还可以指明画出来的形象的<strong>短视频</strong>：做了动画的那台设备把每段短视频作为文件传上去（<code>PUT /v1/blobs/{sha256}</code>，见 <a href="./cloud#the-record">cloud.md</a>），写入 <code>clips: {mood: {sha256, mime, bytes}}</code>；其他设备收到同一个 <code>profile</code> 帧后，从 <code>GET /v1/blobs/{sha256}</code> 下载短视频，不用各自再渲染。短视频随形象走：<code>clips: null</code>、换成别的形象或 <code>DELETE /v1/me/profile</code> 都会清掉。1.0.6 及更早的 App 忽略这个字段。</p><p>0.1.36 起，<strong>对话</strong>也会跟着走，但走的是另一条路：它们的文本经 REST（<code>/v1/sync/*</code>，<a href="./cloud#conversation-sync">cloud.md</a>）进入中继的同步存储，hub 只负责捎个信。中继接受了一次推送之后，或者一次删除之后，账号的每一条<em>其他</em>套接字都会收到 <code>sync {what:&quot;conversations&quot;, cursor, from}</code>（<code>cursor</code> 是变更后账号的计数器，<code>from</code> 是做出变更的设备 id），然后从自己的游标开始拉取新内容。在 <code>from</code> 里看到自己 id 的设备忽略这一帧。0.1.38 起（中继 0.20），hub 还带着<strong>谁在回答</strong>：一台设备在某个同步对话里开始或结束一轮时，会 POST <code>/v1/sync/working</code>，其他套接字收到 <code>working {cid, from, device_name, working, at}</code>；各个 App 在最后一条消息下面显示「kwai 正在处理…」，直到 <code>working: false</code> 到来、回复本身到达，或者过了十分钟。中继 0.31 起，<code>working: true</code> 还会说这一轮在做什么：<code>state</code> 是 <code>working</code> 或 <code>waiting</code>（停在一张卡片上等人），<code>detail</code> 是这一步自己的话，最多 160 个字符，于是那一行读作「kwai 正在处理：打开订票网站」或「kwai 在等你确认」。没带这两个字段的设备照旧显示为正在处理；不认识它们的客户端忽略即可。中继只在内存里保留这些。默认只同步主要聊天；旁聊只在打开了「同时同步旁聊」的设备之间来往。其他什么都不同步：key、服务商和设置留在输入它们的地方，文件和图片留在生成它们的设备上。各个 App 怎么用它，见 <a href="./every-device#the-same-conversations-everywhere">every-device.md</a>。</p><h2 id="the-code" tabindex="-1">代码 <a class="header-anchor" href="#the-code" aria-label="Permalink to &quot;代码 {#the-code}&quot;">​</a></h2><p>各设备的 App 怎样围绕这些帧搭起来（设备页、发给某台设备的旁聊、两端都能回答的审批、电脑自己的手），在 <a href="./every-device">every-device.md</a> 里。</p><ul><li>中继：<a href="https://github.com/nano-muse/nanoMuse/blob/main/cloud/nanomuse_cloud/hub.py" target="_blank" rel="noreferrer"><code>cloud/nanomuse_cloud/hub.py</code></a>：按账号的注册表、路由、<code>GET /v1/devices</code>、<code>DELETE /v1/devices/{id}</code>；控制台在 <a href="https://github.com/nano-muse/nanoMuse/tree/main/cloud/nanomuse_cloud/console/" target="_blank" rel="noreferrer"><code>cloud/nanomuse_cloud/console/</code></a> 下。</li><li>Android：<code>io.github.nanomuse.hub</code>：<code>HubClient</code>（OkHttp，重连）、<code>Hub</code>（状态、偏好、<code>call</code>/<code>find</code>）、<code>HubActions</code>（手机替别人做的事，包括通过无界面聊天运行器执行的 <code>task</code>，其 <code>language</code> 会被遵守）、<code>HubService</code>（前台服务，<code>remoteMessaging</code>）。<code>nanomuse-pc</code>（<code>io.github.nanomuse.reach</code>）从手机的沙箱 shell 访问 hub 上的设备。</li><li>nanoMuse 桌面版：<a href="https://github.com/nano-muse/nanoMuse/blob/main/harness/dsh-nanomuse/src/hub.ts" target="_blank" rel="noreferrer"><code>harness/dsh-nanomuse/src/hub.ts</code></a>（套接字、重连）、<a href="https://github.com/nano-muse/nanoMuse/blob/main/harness/dsh-nanomuse/src/actions.ts" target="_blank" rel="noreferrer"><code>harness/dsh-nanomuse/src/actions.ts</code></a>（这台电脑替别人做的事，远程动作之前的那张卡片）；见 <a href="./desktop">desktop.md</a>。</li><li>iOS：<a href="https://github.com/nano-muse/nanoMuse/blob/main/android/src/ios/NanoMuse/NanoMuseHub.swift" target="_blank" rel="noreferrer"><code>NanoMuse/NanoMuseHub.swift</code></a>：<code>info</code>、<code>open</code>、<code>notify</code>、<code>task</code>（它的 <code>language</code> 会被遵守）、<code>stop</code>；<code>screen</code> 以 <code>no_screen</code> 拒绝，shell 和文件类动作以 <code>not_supported</code> 拒绝。<code>task</code> 里需要批准的一步不会作为 <code>event</code> 发回去：nanoMuse 在前台时手机显示自己的卡片，在后台时这一步被拒绝，回答里会说明。反过来，手机发出的 <code>task</code>（<code>@〈设备〉</code>，<a href="https://github.com/nano-muse/nanoMuse/blob/main/android/src/ios/NanoMuse/NanoMuseDeviceMention.swift" target="_blank" rel="noreferrer"><code>NanoMuseDeviceMention.swift</code></a>）收到的 <code>approval</code> 事件在手机的卡片上回答（<a href="https://github.com/nano-muse/nanoMuse/blob/main/android/src/ios/NanoMuse/NanoMuseRemoteApproval.swift" target="_blank" rel="noreferrer"><code>NanoMuseRemoteApproval.swift</code></a>），<code>approve</code> 发回去；<code>approval_result</code> 关掉卡片。电脑推送的卡片（<a href="#a-computer-s-own-cards-on-the-phone">见上</a>）也落在同一张卡片上，可以选「允许一次」「此定时任务中始终允许」或「拒绝」。那台设备干活的时候回复就在画（<a href="https://github.com/nano-muse/nanoMuse/blob/main/android/src/ios/NanoMuse/NanoMuseDeviceReply.swift" target="_blank" rel="noreferrer"><code>NanoMuseDeviceReply.swift</code></a>）：<code>tool</code>/<code>tool_result</code> 是步骤胶囊，<code>text</code> 来一段显示一段；聊天里的停止按钮发 <code>stop {call}</code>。</li><li>运行时（<code>nanomuse serve</code>）：<a href="https://github.com/nano-muse/nanoMuse/blob/main/nanomuse/cloud.py" target="_blank" rel="noreferrer"><code>nanomuse/cloud.py</code></a>（账号）、<a href="https://github.com/nano-muse/nanoMuse/blob/main/nanomuse/hub/client.py" target="_blank" rel="noreferrer"><code>nanomuse/hub/client.py</code></a>（套接字、重连）、<a href="https://github.com/nano-muse/nanoMuse/blob/main/nanomuse/hub/actions.py" target="_blank" rel="noreferrer"><code>nanomuse/hub/actions.py</code></a>（这台电脑替别人做的事）、<a href="https://github.com/nano-muse/nanoMuse/blob/main/nanomuse/hub/service.py" target="_blank" rel="noreferrer"><code>nanomuse/hub/service.py</code></a>（收到的 <code>task</code> 放进一个可见的旁聊，<code>tool</code>/<code>tool_result</code>/<code>approval</code>/<code>approval_result</code> 各阶段双向传递，设备线程）、<a href="https://github.com/nano-muse/nanoMuse/blob/main/nanomuse/tools/devices.py" target="_blank" rel="noreferrer"><code>nanomuse/tools/devices.py</code></a>（<code>devices</code>、<code>device_*</code>、<code>delegate</code>）；<code>/api/cloud/*</code> 和 <code>/api/hub/*</code> 在 <a href="https://github.com/nano-muse/nanoMuse/blob/main/nanomuse/server/api.py" target="_blank" rel="noreferrer"><code>nanomuse/server/api.py</code></a>。测试：<code>tests/test_hub.py</code>，用一个假中继。</li><li>网页版：<code>DevicesScreen</code>、设备聊天和转发过来的审批卡片，在 <a href="https://github.com/nano-muse/nanoMuse/tree/main/web/src/" target="_blank" rel="noreferrer"><code>web/src/</code></a>；见 <a href="./every-device">every-device.md</a>。</li></ul><h2 id="trust" tabindex="-1">信任 <a class="header-anchor" href="#trust" aria-label="Permalink to &quot;信任 {#trust}&quot;">​</a></h2><p>中继用绑定了设备 id 和类型的凭据验证每一条套接字，并且只在账号内部路由；它存设备名和最后在线时间，不存问了什么。一台设备只回答自己账号的设备，而且只在它的「远程控制」开关开着时，对于任何会在那里运行、读取或写入的事，还要那台设备旁的人同意过（一次，或对发起设备总是允许）。命令在输入它的地方判定，然后才发出；远端 Muse 的审批由发起的人回答，绝不由另一个 Muse 回答。在一台设备上退出登录会在中继吊销那台设备的 key，并把它从 hub 上摘下来；手机和控制台的「设备」列表显示所有登录过的设备，所以你不认识的设备是看得见的，等它离线后「移除」就能把它去掉。</p>`,41)])])}const m=o(n,[["render",s]]);export{h as __pageData,m as default};
